SELECT *, MAX(monthly_fee) OVER (PARTITION BY plan) AS plan_max_monthly_fee, AVG(monthly_fee) OVER (ORDER BY end_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_2_prior, SUM(monthly_fee) OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_monthly_fee, NTILE(5) OVER w_running AS monthly_fee_bucket, ROW_NUMBER() OVER w_recent AS seq_no FROM subscriptions WINDOW w_running AS (PARTITION BY customer_id ORDER BY monthly_fee, id), w_recent AS (PARTITION BY plan, status ORDER BY end_date, id);
